function handler(topic, message) {
    let topics = topic.split("/");
    console.log(111, JSON.stringify(message));  // 修正：stringifg -> stringify

    // 处理 message - 检查类型
    let data;
    if (typeof message === 'string') {
        data = JSON.parse(message);
    } else {
        data = message; // 如果已经是对象，直接使用
    }

    let fields = {};

    // 处理数据 - 添加安全检查
    if (Array.isArray(data)) {
        data.forEach(ele => {
            if (ele && ele.key !== undefined) {
                fields[ele.key] = ele.value;
            }
        });
    } else {
        console.error("message is not an array:", data);
        return [];  // 返回空数组
    }

    let ret = [{
        "table": topics[1], 
        "id": topics[2], 
        "time": new Date().getTime(), 
        "fields": fields
    }];

    console.log(22, JSON.stringify(ret));  // 修正：stringifg -> stringify

    // 返回格式化的数据
    return ret;
}
